import{_ as o,o as d,c,aS as a}from"./chunks/framework.6vsn32Qq.js";const m=JSON.parse('{"title":"UI 公共 interface","description":"","frontmatter":{},"headers":[],"relativePath":"contracts/ui-public-interface.md","filePath":"contracts/ui-public-interface.md","lastUpdated":null}'),t={name:"contracts/ui-public-interface.md"};function r(n,e,l,i,p,s){return d(),c("div",null,[...e[0]||(e[0]=[a('<h1 id="ui-公共-interface" tabindex="-1">UI 公共 interface <a class="header-anchor" href="#ui-公共-interface" aria-label="Permalink to &quot;UI 公共 interface&quot;">​</a></h1><p>状态：当前权威（新增与变更公共契约的治理口径）。当前可发布的组件及子路径仍以 <code>packages/ui/package.json</code> 的 <code>exports</code>、对应 <code>.d.ts</code> 和发布产物为准。</p><h2 id="qy-所有权" tabindex="-1">Qy 所有权 <a class="header-anchor" href="#qy-所有权" aria-label="Permalink to &quot;Qy 所有权&quot;">​</a></h2><p>业务侧依赖的是 Qy 定义的组件名称、props、emits、slots、expose、默认行为和 tokens。每项新增或变更都必须在 Qy 语义下命名、文档化并以组件测试/声明验证；不能把底层库名称、默认行为或实现对象直接提升为业务契约。</p><table tabindex="0"><thead><tr><th>契约面</th><th>Qy 负责的内容</th><th>不应新增为公共依赖的内容</th></tr></thead><tbody><tr><td>props / defaults</td><td>输入语义、默认值与兼容策略</td><td>Element Plus prop 类型、隐式底层默认值</td></tr><tr><td>emits</td><td>事件名、触发时机和 payload</td><td>厂商私有事件或回调对象</td></tr><tr><td>slots</td><td>Qy 命名、上下文与兼容承诺</td><td>底层组件的未封装 slot 细节</td></tr><tr><td>expose</td><td>Qy 明确承诺的方法和返回语义</td><td>组件实例、私有 DOM、VNode/Node/Store</td></tr><tr><td>tokens</td><td>Qy tokens 及其视觉语义</td><td>业务必须直接使用的 <code>--el-*</code> 变量</td></tr></tbody></table><h2 id="当前实现与历史债务" tabindex="-1">当前实现与历史债务 <a class="header-anchor" href="#当前实现与历史债务" aria-label="Permalink to &quot;当前实现与历史债务&quot;">​</a></h2><p>UI 当前维护 Vue 3 + Element Plus implementation，不是已经多框架兼容的 renderer 层。Element Plus 依赖和内部 import 可以存在；新增公共 API 不得扩大厂商类型、实例、私有 DOM/VNode/Node/Store、私有事件或 <code>--el-*</code> 漏泄。</p><p><code>QyInput</code> 与 <code>QyInputNumber</code> 的公开 props、emits、slots、expose 及相关嵌套类型使用 Qy-owned 声明；其实现仍可在内部使用 Element Plus。<code>QyInputNumber</code> 仅承诺 Element Plus 2.9 可支持的核心数字输入 surface，其余厂商扩展不属于稳定契约；包 peer/dev 版本保持 <code>^2.9.0</code> / <code>^2.14.5</code>；业务侧不依赖 Element Plus 类型或实例。</p><h2 id="变更检查" tabindex="-1">变更检查 <a class="header-anchor" href="#变更检查" aria-label="Permalink to &quot;变更检查&quot;">​</a></h2><ol><li>先核对根入口或子路径 exports、对应声明、现有 README 与消费者用法。</li><li>变更 Qy-owned props、emits、slots、expose、defaults 或 tokens 时，补充最小行为/类型证据并保持兼容性口径。</li><li>仅当真实行为差异或复杂边界需要时，建立内部 adapter seam；renderer 决策以 <a href="./../adr/2026-08-06-current-element-implementation-and-future-renderer-seam">当前 Element Plus implementation ADR</a> 为准。</li></ol><p>本契约不决定包版本、构建格式或 npm 解析；这些见 <a href="./package-exports-and-runtime">包 exports 与宿主 runtime</a>。</p><h2 id="qypopconfirm" tabindex="-1">QyPopconfirm <a class="header-anchor" href="#qypopconfirm" aria-label="Permalink to &quot;QyPopconfirm&quot;">​</a></h2><p><code>QyPopconfirm</code> 的稳定面是 Qy-owned 的确认语义：<code>title</code>、受控/非受控 <code>open</code>、<code>confirmLoading</code>、<code>closeOnConfirm</code>、<code>variant</code>、<code>confirmType</code>、<code>placement</code> 与 <code>width</code>。插槽仅承诺 <code>reference</code>、<code>title</code> 和 <code>icon</code>；事件为 <code>update:open</code>、<code>open-change</code>、<code>confirm</code>、<code>cancel</code> 与携带 Qy 关闭原因的 <code>close(reason)</code>。业务侧不依赖 Element Plus 实例、原始事件对象、teleport/popper 参数或底层 CSS 变量。</p><h2 id="qydialog" tabindex="-1">QyDialog <a class="header-anchor" href="#qydialog" aria-label="Permalink to &quot;QyDialog&quot;">​</a></h2><p><code>QyDialog</code> 的稳定面是受控 <code>open</code>、<code>update:open</code>、<code>open-change</code>、<code>confirm</code>、<code>cancel</code>、<code>close(reason)</code>、<code>opened</code> 和 <code>closed</code>。<code>QyDialogCloseReason</code> 冻结为 <code>confirm | cancel | header | escape | overlay | external</code>。默认 footer 由 <code>showFooter</code>、<code>showConfirm</code>、<code>showCancel</code>、<code>confirmText</code>、<code>cancelText</code>、<code>confirmLoading</code> 和 <code>confirmDisabled</code> 控制；宿主持有异步业务并在成功后关闭，Dialog 不接收任意业务 Promise。</p><p>宽度、顶部距离、全屏、最小化、销毁、拖拽、锁滚动和显式关闭策略均使用 Qy-owned props。<code>header</code>、<code>footer</code>、<code>footer-left</code> 和 <code>footer-append</code> 是稳定 slot；唯一公开方法为 <code>handleMinimize()</code>。公共类型不暴露 Element Plus props、实例、原始事件、DOM/VNode/Node/Store 或 <code>--el-*</code>。</p><p>旧 <code>modelValue</code>、字符串 <code>layout</code>、<code>confirmProps</code>、<code>ok</code> 和任意 Element attrs 由独立 <code>@qynpm/qy-dialog-legacy</code> 薄 adapter 过渡承接，不进入 QyDialog 当前契约，也不作为新业务 API。</p><h2 id="qyinputtag" tabindex="-1">QyInputTag <a class="header-anchor" href="#qyinputtag" aria-label="Permalink to &quot;QyInputTag&quot;">​</a></h2><p><code>QyInputTag</code> 的稳定面是 Qy-owned 的受控字符串数组：<code>modelValue?: string[]</code> 默认归一化为 <code>[]</code>；<code>max</code>、<code>trigger?: &#39;enter&#39; | &#39;space&#39;</code>、<code>tagTone</code>、<code>tagEffect</code>、<code>size</code>、<code>clearable</code>、<code>disabled</code>、<code>readonly</code>、<code>placeholder</code>、<code>autofocus</code>、<code>validateEvent</code>、<code>id</code>、<code>tabindex</code>、<code>maxlength</code>、<code>minlength</code>、<code>autocomplete</code> 和 <code>ariaLabel</code> 均按 Qy 声明提供。<code>trigger</code> 使用小写 Qy 值，内部才映射为当前 implementation 所需的 Enter/Space；<code>tagTone</code> 与 <code>tagEffect</code> 使用 Qy 标签类型，<code>neutral</code> 只在内部映射为实现层的语义色。</p><p>事件为 <code>update:modelValue(string[])</code>、<code>change(string[])</code>、<code>input(string)</code>、<code>add(string)</code>、<code>remove(value, index)</code>、<code>clear</code>、<code>focus(FocusEvent)</code> 和 <code>blur(FocusEvent)</code>。Element Plus 清空时可能给出 <code>undefined</code>，Qy 对外始终发出 <code>[]</code>；一次接受的 add/remove/clear 变更只发出一次 Qy <code>change</code>。删除索引从变更前的 Qy 数组推导，业务侧不接触厂商 tag 对象或私有事件 payload。插槽仅承诺 <code>tag({ value, index })</code>、<code>prefix</code> 和 <code>suffix</code>；唯一公开方法是 <code>focus()</code> 与 <code>blur()</code>。</p><p>该组件当前由 Element Plus <code>ElInputTag</code> 适配实现，Element Plus 类型、组件实例、<code>draggable</code>、折叠标签、厂商事件名以及 DOM/VNode/Node/Store 不属于公共契约。当前版本不提供 delimiter、逗号或 Tab 提交、拖拽/重排、折叠标签、<code>v-model:value</code> 或 <code>removeTag</code> 兼容；业务侧只依赖上述 Qy props、事件、插槽和 expose。</p><h2 id="qymoneyinput" tabindex="-1">QyMoneyInput <a class="header-anchor" href="#qymoneyinput" aria-label="Permalink to &quot;QyMoneyInput&quot;">​</a></h2><p><code>QyMoneyInput</code> 是金额录入包装层，稳定 props 为 <code>modelValue?: string | number | null</code>、<code>precision</code>、<code>min</code>、<code>max</code>、<code>allowNegative</code>、<code>formatTrigger?: &#39;blur&#39; | &#39;change&#39; | &#39;none&#39;</code>、<code>emptyValue</code>，以及安全输入 surface <code>placeholder</code>、<code>clearable</code>、<code>disabled</code>、<code>readonly</code>、<code>size</code>、<code>name</code>、<code>id</code>、<code>autocomplete</code>、<code>autofocus</code>、<code>maxlength</code>、<code>minlength</code>、<code>tabindex</code> 和 <code>ariaLabel</code>。输入阶段清洗非法字符，按 <code>formatTrigger</code> 在 blur/change/none 时格式化，用户编辑相关的 <code>update:modelValue</code>、<code>input</code> 和 <code>change</code> payload 始终为字符串。</p><p>事件还包括 <code>focus(FocusEvent)</code>、<code>blur(FocusEvent)</code>、<code>clear()</code> 和 <code>enter(KeyboardEvent)</code>；插槽仅承诺无 payload 的 <code>prefix</code>、<code>suffix</code>、<code>prepend</code>、<code>append</code>。稳定 expose 为 <code>focus()</code>、<code>blur()</code>、<code>select()</code> 和 <code>clear()</code>。当前实现暂保留 <code>getNativeInput()</code> 运行时兼容方法，但其原生 DOM 返回值不属于 Qy 稳定类型契约，新消费者不应依赖。</p><p>根入口和 <code>@qynpm/ui/qy-money-input</code> 子入口共享同一 Qy-owned props、events、slots 和 expose 声明；Element Plus 类型、组件实例、私有 DOM/VNode/Node/Store 以及货币换算、财务校验和提交逻辑不属于该组件的公共边界。</p><h2 id="qywatermark" tabindex="-1">QyWatermark <a class="header-anchor" href="#qywatermark" aria-label="Permalink to &quot;QyWatermark&quot;">​</a></h2><p><code>QyWatermark</code> 的稳定面是容器内平铺水印：<code>content</code>、<code>image</code>、<code>zIndex</code>、<code>rotate</code>、<code>width</code>、<code>height</code>、<code>gap</code>、<code>offset</code> 和 Qy-owned <code>font</code>；只承诺 <code>default</code> 插槽。图片优先，加载失败回退到文字；覆盖层不接收指针事件，容器变化和当前 renderer 可观察到的节点篡改由内部实现恢复。业务侧只依赖安全容器属性 <code>class</code>、<code>style</code>、<code>id</code>、<code>title</code>、<code>role</code>、<code>data-*</code>、<code>aria-*</code>，不依赖 Element Plus props、实例、DOM、事件、expose 或 CSS 变量。</p><h2 id="qyiframe" tabindex="-1">QyIframe <a class="header-anchor" href="#qyiframe" aria-label="Permalink to &quot;QyIframe&quot;">​</a></h2><p><code>QyIframe</code> 的稳定面是带必填 <code>src</code> 与无障碍 <code>title</code> 的原生嵌入页面；二者去除首尾空白后任一为空时不渲染 iframe。<code>src</code> 变化时更新地址，<code>reloadKey?: string | number</code> 变化时重建 iframe，使相同地址也可受控 reload。组件支持 <code>loading</code>、<code>sandbox</code>、<code>allow</code>、<code>referrerPolicy</code>、<code>allowFullscreen</code>，<code>load</code> 与 <code>error</code> 仅为无参数通知，不暴露 DOM Event。组件填满宿主提供的容器，不感知应用头部高度，不覆盖全局 resize 监听，不模拟加载时长，也不接管会话、地址白名单或跨域通信。业务侧只依赖安全根属性，不依赖 DOM ref、Element Plus 或宿主运行时对象。</p>',29)])])}const f=o(t,[["render",r]]);export{m as __pageData,f as default};
